import{_t as e,it as t,n,rt as r}from"./chunks/framework.BVGGWBQY.js";var i=JSON.parse(`{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":1788874077000}`),a={name:`guide/getting-started.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to “Getting started”">​</a></h1><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to “Requirements”">​</a></h2><ul><li>Node.js 22 or newer, or Docker.</li><li>A CardDAV server and an account on it.</li></ul><h2 id="credentials" tabindex="-1">Credentials <a class="header-anchor" href="#credentials" aria-label="Permalink to “Credentials”">​</a></h2><p>CardDAV authenticates with <strong>an account name and a password</strong>, over HTTP Basic. There is no API key to mint and no scopes to choose — which is the first thing to say plainly, because most MCP servers want a token and this one does not.</p><p>Most hosted services want an <strong>app-specific password</strong> rather than your account password. Nextcloud, Fastmail and iCloud all issue one per application, and using one means this server holds a credential you can revoke on its own:</p><ul><li><strong>Nextcloud</strong> — Settings → Security → Devices &amp; sessions → <em>Create new app password</em>.</li><li><strong>Fastmail</strong> — Settings → Privacy &amp; Security → Integrations → <em>New app password</em>, scoped to Contacts.</li><li><strong>iCloud</strong> — appleid.apple.com → Sign-In and Security → App-Specific Passwords.</li><li><strong>Radicale, Baikal, SOGo</strong> — whatever account the server itself was configured with.</li></ul><p><code>CARDDAV_TOKEN</code> exists for the rare server that wants a bearer token instead. Almost nothing does; if you are not sure, you want the username and password.</p><h2 id="finding-the-url" tabindex="-1">Finding the URL <a class="header-anchor" href="#finding-the-url" aria-label="Permalink to “Finding the URL”">​</a></h2><p><code>CARDDAV_URL</code> is the <strong>root</strong> of the CardDAV server, not one address book. The principal and the address book home set are discovered from it.</p><table tabindex="0"><thead><tr><th>Server</th><th>URL</th></tr></thead><tbody><tr><td>Nextcloud</td><td><code>https://cloud.example.net/remote.php/dav</code></td></tr><tr><td>Baikal</td><td><code>https://example.net/dav.php</code></td></tr><tr><td>Radicale</td><td><code>https://example.net:5232</code></td></tr><tr><td>Fastmail</td><td><code>https://carddav.fastmail.com</code></td></tr><tr><td>mailbox.org</td><td><code>https://dav.mailbox.org</code></td></tr><tr><td>iCloud</td><td><code>https://contacts.icloud.com</code></td></tr></tbody></table><p>If all you have is the URL of a single address book — the one a desktop client&#39;s settings shows — paste that. The server recognises a collection URL and limits itself to that one book, and says so.</p><h2 id="the-shortest-working-example" tabindex="-1">The shortest working example <a class="header-anchor" href="#the-shortest-working-example" aria-label="Permalink to “The shortest working example”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">CARDDAV_URL</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">https://dav.example.net</span><span style="--shiki-light:#953800;--shiki-dark:#FFA657;"> \\</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">CARDDAV_USERNAME=you </span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">\\</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">CARDDAV_PASSWORD=your-app-password </span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">\\</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">npx </span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;">-y</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> @ni-c/carddav-mcp</span></span></code></pre></div><p>That is the whole configuration. The server prints one line to stderr saying what it is pointed at and then speaks MCP on stdin and stdout — so running it in a terminal like this is only useful to see that line. To actually use it, register it with a client: <a href="/guide/clients">connecting clients</a>.</p><h2 id="checking-it-works" tabindex="-1">Checking it works <a class="header-anchor" href="#checking-it-works" aria-label="Permalink to “Checking it works”">​</a></h2><p>Ask for <code>list_address_books</code> first. It is the only tool that always asks the server rather than answering from a cache, so it is the one that proves the credentials, the URL and the discovery walk all work at once.</p><p>If something is off, <code>get_server_info</code> is the next call. It reports the DAV compliance tokens, which vCard versions each book accepts, and whether the two optional features this server can use — server-side search and RFC 6578 sync — actually work on this instance. It probes rather than trusting what the server advertises, because a server can claim <code>addressbook</code> and still refuse a filtered query.</p><h2 id="narrowing-it-down" tabindex="-1">Narrowing it down <a class="header-anchor" href="#narrowing-it-down" aria-label="Permalink to “Narrowing it down”">​</a></h2><p>Two things are worth setting before pointing this at an account that matters:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">CARDDAV_ADDRESSBOOKS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">work</span><span style="--shiki-light:#6E7781;--shiki-dark:#8B949E;">          # only this book is visible at all</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">CARDDAV_READ_ONLY</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">true</span><span style="--shiki-light:#6E7781;--shiki-dark:#8B949E;">             # only the read tools are registered</span></span></code></pre></div><p>The first is a fence: everything else on the account stays invisible, and it is enforced where an id is decoded rather than at the edge of each tool. The second means the write tools are not registered — they do not appear in <code>tools/list</code> and cannot be called. Both are described in <a href="/guide/configuration">configuration</a>.</p>`,22)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};